output:
case "$1" in
  ''|*[!0-9]*) exit 1;;
esac

case "$1" in
  start)   echo starting;;
  stop)    echo stopping;;
  restart) echo restarting;;
  *)       echo "unknown: $1"; exit 1;;
esac

case "$val" in
  (yes|no|maybe) echo matched;;
  (*) echo no match;;
esac

case "$1" in
  *.sh)  echo shell;;
  *.py)  echo python;;
  *.txt) echo text;;
  *)     echo other;;
esac
